\begin{align*}
\sum_{n = 1}^\infty \frac{F_{n + 1}}{F_n F_{n + 2}} &= \frac{1}{F_1 F_3} + \frac{1}{F_2} - \lim_{n \to \infty} \frac{1}{F_{n+1}} \\
